package com.wizzadrds.theworldremembers.voice; public record VoiceDelivery(float rate,float pitch,float volume){public VoiceDelivery{if(rate<=0||pitch<=0||volume<0||volume>1)throw new IllegalArgumentException();}public static VoiceDelivery resolve(VoiceProfile p,VoiceDeliveryState s){float r=p.rate(),pi=p.pitch(),v=1f;switch(s){case TIMID->v=.65f;case NERVOUS->r*=1.15f;case TIRED->r*=.78f;case ANGRY->r*=1.08f;case EXCITED->r*=1.2f;default->{}}return new VoiceDelivery(Math.min(2,r),pi,v);}}
